function clamp(v, lo, hi) { return Math.max(lo, Math.min(hi, v)); }

function nearestOvrKey(typicalByOvr, ovr, ovrMin, ovrMax) {
  const target = clamp(ovr, ovrMin, ovrMax);
  if (typicalByOvr[String(target)]) return String(target);
  // walk outward until we find a populated key (sparse fallback safety net)
  for (let d = 1; d <= (ovrMax - ovrMin); d++) {
    const up = target + d, down = target - d;
    if (up <= ovrMax && typicalByOvr[String(up)]) return String(up);
    if (down >= ovrMin && typicalByOvr[String(down)]) return String(down);
  }
  return Object.keys(typicalByOvr)[0];
}

function predictOvr(model, values) {
  let sum = model.coefficients.Intercept || 0;
  for (const p of model.predictors) {
    sum += (model.coefficients[p] || 0) * (values[p] ?? model.positionMedian[p]);
  }
  return clamp(Math.round(sum), 40, 99);
}

function suggestIncreases(model, values, predicted, target) {
  const gap = target - predicted;
  if (gap <= 0) return { gap, plan: [] };
  const positive = model.predictors
    .map((p) => ({ p, coef: model.coefficients[p] || 0 }))
    .filter((x) => x.coef > 0)
    .sort((a, b) => b.coef - a.coef)
    .slice(0, 5);
  if (positive.length === 0) return { gap, plan: [] };
  const perAttrGap = gap / positive.length;
  const plan = positive.map(({ p, coef }) => {
    const current = values[p] ?? model.positionMedian[p];
    let increase = Math.ceil(perAttrGap / coef);
    increase = clamp(increase, 0, 99 - current);
    return { attribute: p, current, increase, newValue: current + increase };
  });
  return { gap, plan };
}

const ATTR_COLOR_MINE = "#2563eb";
const ATTR_COLOR_TYPICAL = "#ea580c";

export default function MaddenRadarAnalyzer() {
  const positions = MADDEN_DATA.positions;
  const [position, setPosition] = useState(positions[0]);
  const model = MADDEN_DATA.models[position];

  const [values, setValues] = useState(() => ({ ...model.positionMedian }));
  const [targetOvr, setTargetOvr] = useState(null);

  const handlePositionChange = (newPos) => {
    const m = MADDEN_DATA.models[newPos];
    setPosition(newPos);
    setValues({ ...m.positionMedian });
    setTargetOvr(null);
  };

  const predicted = useMemo(() => predictOvr(model, values), [model, values]);
  const comparisonOvr = targetOvr ?? predicted;
  const typicalKey = nearestOvrKey(model.typicalByOvr, comparisonOvr, model.ovrMin, model.ovrMax);
  const typical = model.typicalByOvr[typicalKey];

  const radarData = model.predictors.map((p) => ({
    attribute: p,
    "My Build": values[p] ?? model.positionMedian[p],
    "Typical": typical[p],
  }));

  const { gap, plan } = useMemo(
    () => suggestIncreases(model, values, predicted, targetOvr ?? predicted),
    [model, values, predicted, targetOvr]
  );

  return (
    <div className="w-full min-h-screen bg-slate-50 p-6 font-sans">
      <div className="max-w-5xl mx-auto">
        <h1 className="text-2xl font-bold text-slate-800 mb-1">
          Madden 26 Rating Requirements Analyzer
        </h1>
        <p className="text-sm text-slate-500 mb-6">
          Data-driven per-position regression models (R² up to 0.99) built from 2,035 real Madden 26 players.
        </p>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          {/* Controls */}
          <div className="md:col-span-1 bg-white rounded-xl shadow-sm border border-slate-200 p-5 h-fit">
            <label className="block text-xs font-semibold text-slate-500 uppercase mb-1">
              Position
            </label>
            <select
              className="w-full border border-slate-300 rounded-lg px-3 py-2 mb-4 text-sm"
              value={position}
              onChange={(e) => handlePositionChange(e.target.value)}
            >
              {positions.map((p) => (
                <option key={p} value={p}>{p}</option>
              ))}
            </select>

            <label className="block text-xs font-semibold text-slate-500 uppercase mb-1">
              Target OVR (optional)
            </label>
            <input
              type="number"
              min={model.ovrMin}
              max={model.ovrMax}
              placeholder={`${model.ovrMin}-${model.ovrMax}`}
              className="w-full border border-slate-300 rounded-lg px-3 py-2 mb-4 text-sm"
              value={targetOvr ?? ""}
              onChange={(e) => {
                const v = e.target.value;
                setTargetOvr(v === "" ? null : clamp(parseInt(v, 10), model.ovrMin, model.ovrMax));
              }}
            />

            <div className="text-xs font-semibold text-slate-500 uppercase mb-2">Attributes</div>
            <div className="space-y-3 max-h-[420px] overflow-y-auto pr-1">
              {model.predictors.map((p) => (
                <div key={p}>
                  <div className="flex justify-between text-xs text-slate-600 mb-1">
                    <span>{p}</span>
                    <span className="font-semibold">{values[p] ?? model.positionMedian[p]}</span>
                  </div>
                  <input
                    type="range"
                    min={0}
                    max={99}
                    value={values[p] ?? model.positionMedian[p]}
                    onChange={(e) =>
                      setValues((v) => ({ ...v, [p]: parseInt(e.target.value, 10) }))
                    }
                    className="w-full accent-blue-600"
                  />
                </div>
              ))}
            </div>
          </div>

          {/* Results */}
          <div className="md:col-span-2 space-y-6">
            <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-5">
              <div className="flex items-baseline justify-between">
                <div>
                  <div className="text-xs font-semibold text-slate-500 uppercase">Predicted Overall</div>
                  <div className="text-4xl font-bold text-slate-800">{predicted}</div>
                </div>
                <div className="text-right text-xs text-slate-500">
                  <div>Model fit: R² = {model.r2}</div>
                  <div>n = {model.n} players</div>
                </div>
              </div>

              {targetOvr != null && (
                <div className="mt-3 text-sm">
                  {gap <= 0 ? (
                    <span className="text-emerald-600 font-medium">
                      You already meet or exceed {targetOvr} OVR with this build.
                    </span>
                  ) : (
                    <span className="text-slate-600">
                      {gap} point{gap === 1 ? "" : "s"} short of {targetOvr} OVR.
                    </span>
                  )}
                </div>
              )}
            </div>

            <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-5">
              <div className="text-sm font-semibold text-slate-700 mb-2">
                Your build vs. typical {comparisonOvr} OVR {position}
              </div>
              <ResponsiveContainer width="100%" height={380}>
                <RadarChart data={radarData} outerRadius="75%">
                  <PolarGrid stroke="#e2e8f0" />
                  <PolarAngleAxis dataKey="attribute" tick={{ fontSize: 10, fill: "#475569" }} />
                  <PolarRadiusAxis angle={90} domain={[0, 99]} tick={{ fontSize: 9, fill: "#94a3b8" }} />
                  <Radar name="My Build" dataKey="My Build" stroke={ATTR_COLOR_MINE}
                         fill={ATTR_COLOR_MINE} fillOpacity={0.25} />
                  <Radar name={`Typical ${comparisonOvr} OVR`} dataKey="Typical" stroke={ATTR_COLOR_TYPICAL}
                         fill={ATTR_COLOR_TYPICAL} fillOpacity={0.15} />
                  <Legend wrapperStyle={{ fontSize: 12 }} />
                  <Tooltip />
                </RadarChart>
              </ResponsiveContainer>
            </div>

            {targetOvr != null && gap > 0 && plan.length > 0 && (
              <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-5">
                <div className="text-sm font-semibold text-slate-700 mb-3">
                  To reach {targetOvr} OVR
                </div>
                <table className="w-full text-sm">
                  <thead>
                    <tr className="text-left text-xs text-slate-500 uppercase border-b border-slate-200">
                      <th className="pb-2">Attribute</th>
                      <th className="pb-2">Current</th>
                      <th className="pb-2">Increase</th>
                      <th className="pb-2">New Value</th>
                    </tr>
                  </thead>
                  <tbody>
                    {plan.map((row) => (
                      <tr key={row.attribute} className="border-b border-slate-100 last:border-0">
                        <td className="py-1.5 text-slate-700">{row.attribute}</td>
                        <td className="py-1.5 text-slate-500">{row.current}</td>
                        <td className="py-1.5 text-orange-600 font-semibold">+{row.increase}</td>
                        <td className="py-1.5 text-slate-800 font-medium">{row.newValue}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}
